document.addEventListener('DOMContentLoaded', function () {
    'use strict';
    const mobileMenuToggle = document.getElementById('mobile-menu-toggle');
    const mobileNav = document.getElementById('mobile-nav');
    const mobileNavOverlay = document.getElementById('mobile-nav-overlay');
    const mobileNavClose = document.getElementById('mobile-nav-close');
    const categoriesToggle = document.getElementById('categories-btn');
    const categoriesMenu = document.getElementById('categories-menu');
    const header = document.getElementById('main-header');
    function openMobileMenu() {
        if (mobileNav && mobileNavOverlay) {
            mobileNav.classList.add('active');
            mobileNavOverlay.classList.add('active');
            document.body.style.overflow = 'hidden';
        }
    }
    function closeMobileMenu() {
        if (mobileNav && mobileNavOverlay) {
            mobileNav.classList.remove('active');
            mobileNavOverlay.classList.remove('active');
            document.body.style.overflow = '';
        }
    }
    if (mobileMenuToggle) {
        mobileMenuToggle.addEventListener('click', openMobileMenu);
    }
    if (mobileNavClose) {
        mobileNavClose.addEventListener('click', closeMobileMenu);
    }
    if (mobileNavOverlay) {
        mobileNavOverlay.addEventListener('click', closeMobileMenu);
    }
    document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') {
            closeMobileMenu();
            closeDropdown();
        }
    });
    function handleHeaderScroll() {
        if (!header) return;
        if (window.scrollY > 10) {
            header.style.boxShadow = '0 2px 12px rgba(0,0,0,0.08)';
        } else {
            header.style.boxShadow = 'none';
        }
    }
    window.addEventListener('scroll', handleHeaderScroll, { passive: true });
    handleHeaderScroll();
    function openDropdown() {
        if (categoriesToggle && categoriesMenu) {
            categoriesToggle.setAttribute('aria-expanded', 'true');
            categoriesMenu.removeAttribute('hidden');
            requestAnimationFrame(() => {
                categoriesMenu.classList.add('active');
            });
        }
    }
    function closeDropdown() {
        if (categoriesToggle && categoriesMenu) {
            categoriesToggle.setAttribute('aria-expanded', 'false');
            categoriesMenu.classList.remove('active');
            setTimeout(() => {
                if (categoriesToggle.getAttribute('aria-expanded') === 'false') {
                    categoriesMenu.setAttribute('hidden', '');
                }
            }, 200);
        }
    }
    if (categoriesToggle && categoriesMenu) {
        categoriesToggle.addEventListener('click', function (e) {
            e.stopPropagation();
            const isExpanded = categoriesToggle.getAttribute('aria-expanded') === 'true';
            if (isExpanded) {
                closeDropdown();
            } else {
                openDropdown();
            }
        });
        document.addEventListener('click', function (e) {
            if (!categoriesToggle.contains(e.target) && !categoriesMenu.contains(e.target)) {
                closeDropdown();
            }
        });
    }
    const mobileDropdownBtn = document.querySelector('.osm-mobile-menu__dropdown-btn');
    const mobileDropdownMenu = document.getElementById('mobile-categories-menu');
    if (mobileDropdownBtn && mobileDropdownMenu) {
        mobileDropdownBtn.addEventListener('click', function (e) {
            e.stopPropagation();
            const isExpanded = mobileDropdownBtn.getAttribute('aria-expanded') === 'true';
            if (isExpanded) {
                mobileDropdownBtn.setAttribute('aria-expanded', 'false');
                mobileDropdownMenu.style.maxHeight = null;
                setTimeout(() => {
                    if (mobileDropdownBtn.getAttribute('aria-expanded') === 'false') {
                        mobileDropdownMenu.setAttribute('hidden', '');
                    }
                }, 300);
            } else {
                mobileDropdownMenu.removeAttribute('hidden');
                mobileDropdownBtn.setAttribute('aria-expanded', 'true');
                mobileDropdownMenu.style.maxHeight = mobileDropdownMenu.scrollHeight + 'px';
            }
        });
    }
});